import{c as t,Q as a,j as i,m as l}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"费用与到账说明 - Hyperliquid 找回机器人服务费标准","description":"透明公示恢复服务费率（0.5%）及链上提现规费（2 USDC）。教你如何计算预估到账金额：实际到账 = 可恢复价值 - 总费用。","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/zh/fee-and-settlement"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/fee-and-settlement"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/fee-and-settlement"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/fee-and-settlement"}],["meta",{"name":"keywords","content":"Hyperliquid找回服务费, 提现手续费, Web3找回成本, 提现到账时间"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"费用与到账说明 - Hyperliquid 找回机器人服务费标准"}],["meta",{"property":"og:description","content":"透明公示恢复服务费率（0.5%）及链上提现规费（2 USDC）。教你如何计算预估到账金额：实际到账 = 可恢复价值 - 总费用。"}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/zh/fee-and-settlement"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"费用与到账说明 - Hyperliquid 找回机器人服务费标准"}],["meta",{"name":"twitter:description","content":"透明公示恢复服务费率（0.5%）及链上提现规费（2 USDC）。教你如何计算预估到账金额：实际到账 = 可恢复价值 - 总费用。"}]]},"headers":[],"relativePath":"zh/fee-and-settlement.md","filePath":"zh/fee-and-settlement.md","lastUpdated":null}'),r={name:"zh/fee-and-settlement.md"};function n(d,e,o,s,h,c){return a(),i("div",null,[...e[0]||(e[0]=[l(`<h1 id="费用与到账" tabindex="-1">费用与到账 <a class="header-anchor" href="#费用与到账" aria-label="Permalink to &quot;费用与到账&quot;">​</a></h1><p>本文说明您可能支付的费用、费用如何计算，以及最终预计会收到多少资产。</p><h2 id="费用术语" tabindex="-1">费用术语 <a class="header-anchor" href="#费用术语" aria-label="Permalink to &quot;费用术语&quot;">​</a></h2><ul><li><code>Service Fee</code>：服务费，按恢复金额的 0.5% 计算，最低 1 USDC。</li><li><code>Withdrawal Fees</code>：提现手续费，Hyperliquid 每次提现固定 1 USDC。</li><li><code>Total Cost</code>：总成本，等于 Service Fee + Withdrawal Fees。</li><li><code>You Will Receive</code>：用户预计到账，等于预估可恢复价值 - Total Cost。</li></ul><p>其中“预估可恢复价值”指本次实际能够处理的资产价值；仍处于锁定或等待状态的资产，暂时不会计入。</p><h2 id="费用结构" tabindex="-1">费用结构 <a class="header-anchor" href="#费用结构" aria-label="Permalink to &quot;费用结构&quot;">​</a></h2><p>恢复通常包含两次提现，因此 <code>Withdrawal Fees = 2 USDC</code>：</p><ol><li>服务费提现：1 USDC 平台手续费</li><li>最终提现：1 USDC 平台手续费</li></ol><h2 id="计算公式" tabindex="-1">计算公式 <a class="header-anchor" href="#计算公式" aria-label="Permalink to &quot;计算公式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service Fee = max(预估可恢复价值 × 0.5%, 1 USDC)</span></span>
<span class="line"><span>Withdrawal Fees = 2 USDC</span></span>
<span class="line"><span>Total Cost = Service Fee + Withdrawal Fees</span></span>
<span class="line"><span>You Will Receive = 预估可恢复价值 - Total Cost</span></span></code></pre></div><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>预估可恢复价值</th><th>Service Fee</th><th>Withdrawal Fees</th><th>Total Cost</th><th>You Will Receive</th></tr></thead><tbody><tr><td>100 USDC</td><td>1.00</td><td>2.00</td><td>3.00</td><td>97.00</td></tr><tr><td>1,000 USDC</td><td>5.00</td><td>2.00</td><td>7.00</td><td>993.00</td></tr><tr><td>10,000 USDC</td><td>50.00</td><td>2.00</td><td>52.00</td><td>9,948.00</td></tr></tbody></table><h2 id="结果页会如何显示" tabindex="-1">结果页会如何显示 <a class="header-anchor" href="#结果页会如何显示" aria-label="Permalink to &quot;结果页会如何显示&quot;">​</a></h2><ul><li>执行前：显示预估值（Estimated）。</li><li>执行后：显示实际值（Actual）。</li><li>预估与实际之间可能会因为执行期间价格变化而出现轻微差异。</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>地址检测永久免费。</li><li>若本次没有成功处理任何资产，就不会产生不必要的服务费扣除。</li><li>最终提现仍需满足 Hyperliquid 的最小提现要求（常见阈值 1.01 USDC）。</li><li>提现发起后，到 Arbitrum 的到账时间取决于 Hyperliquid 的处理速度，可能需要几分钟到十几分钟。</li></ul>`,16)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
